"""Observe selected generated byte accesses without substituting replay values.

This diagnoses guest shared state after boundary inputs match. Backups and
hashes stay local. No generated function body is emitted by this tool.
"""
import argparse
import hashlib
import json
from pathlib import Path
import re


def instrument(text, address, offsets, stores=False):
    m = re.search(r'^DEFINE_REX_FUNC\(sub_' + address + r'\) \{\n(.*?)^\}', text, re.M | re.S)
    if not m or 'Kind::kGuestMemory' in m[1]:
        raise ValueError('missing or already instrumented native definition')
    if stores:
        pattern = r'(?m)^(\s*REX_STORE_U8\(ctx\.(\w+)\.u32 \+ (\d+), ctx\.(\w+)\.u8\);)$'
    else:
        pattern = r'(?m)^(\s*ctx\.(\w+)\.u64 = REX_LOAD_U8\(ctx\.(\w+)\.u32 \+ (\d+)\);)$'
    count = 0
    def replace(match):
        nonlocal count
        base, offset, value = ((match[2], int(match[3]), match[4]) if stores
                               else (match[3], int(match[4]), match[2]))
        if offset not in offsets:
            return match[0]
        if not stores and base == value:
            raise ValueError('load overwrites its address register')
        count += 1
        key = (int(address, 16) << 32) | offset | ((1 << 31) if stores else 0)
        return (match[0] + '\n\tif (rex::session_probe::Enabled()) '
                f'rex::session_probe::Scalar(rex::session_probe::Kind::kGuestMemory, UINT64_C({key}), '
                f'(uint64_t(ctx.{base}.u32) << 32) | uint8_t(ctx.{value}.u64));')
    body = re.sub(pattern, replace, m[1])
    if not count:
        raise ValueError('no selected accesses')
    result = text[:m.start(1)] + body + text[m.end(1):]
    if '#include <rex/session_probe.h>' not in result:
        result = '#include <rex/session_probe.h>\n' + result
    return result, count


def digest(data):
    return hashlib.sha256(data).hexdigest()


if __name__ == '__main__':
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument('--generated', type=Path)
    p.add_argument('--function')
    p.add_argument('--offset', type=int, action='append')
    p.add_argument('--stores', action='store_true')
    p.add_argument('--backup', type=Path)
    p.add_argument('--restore', action='store_true')
    p.add_argument('--self-test', action='store_true')
    a = p.parse_args()
    if a.self_test:
        src = 'DEFINE_REX_FUNC(sub_00000001) {\n ctx.r4.u64 = REX_LOAD_U8(ctx.r3.u32 + 8);\n}\n'
        out, n = instrument(src, '00000001', [8])
        assert n == 1 and 'kGuestMemory' in out
        src = 'DEFINE_REX_FUNC(sub_00000001) {\n REX_STORE_U8(ctx.r3.u32 + 8, ctx.r4.u8);\n}\n'
        assert instrument(src, '00000001', [8], True)[1] == 1
        print('session memory observation self-test passed')
    elif a.restore:
        meta = json.loads((a.backup / 'manifest.json').read_text(encoding='utf-8'))
        target = Path(meta['path'])
        assert digest(target.read_bytes()) == meta['instrumented_sha256'], 'partition changed'
        original = (a.backup / 'original.bin').read_bytes()
        assert digest(original) == meta['original_sha256']
        target.write_bytes(original)
        print('restored', target.name)
    else:
        if not all((a.generated, a.function, a.offset, a.backup)):
            p.error('--generated, --function, --offset and --backup required')
        found = [x for x in a.generated.glob('*_recomp.*.cpp')
                 if f'DEFINE_REX_FUNC(sub_{a.function})' in x.read_text(encoding='utf-8')]
        assert len(found) == 1, 'ambiguous native definition'
        target = found[0].resolve()
        original = target.read_bytes()
        output, n = instrument(original.decode('utf-8'), a.function, a.offset, a.stores)
        output = output.encode('utf-8')
        a.backup.mkdir(parents=True, exist_ok=False)
        (a.backup / 'original.bin').write_bytes(original)
        (a.backup / 'manifest.json').write_text(json.dumps({
            'path': str(target), 'accesses': n, 'original_sha256': digest(original),
            'instrumented_sha256': digest(output)}, indent=2), encoding='utf-8')
        target.write_bytes(output)
        print('instrumented', target.name, n, 'accesses')
